Algorithm LAGRANGIAN_HIERARCHICAL_PATCHING(problem_spec, time_limit, params, seed)
  Init hooks: ENCODE, DECODE, COST, CONSTRAINTS, RELAX_SOLVER, PATCHER, CLUSTER, PARTIAL_OPT
  x_best ← construct_greedy_seed(problem_spec, seed); best_cost ← COST(x_best); multipliers ← zero(CONSTRAINTS)
  coarse_hierarchy ← build_multilevel_coarsening(problem_spec, params.levels)
  while not stop(time_limit, improvement_tol):
    // 1. Relaxed master solve under current multipliers (continuous/LP/penalized heuristic)
    x_relaxed ← RELAX_SOLVER(problem_spec, multipliers, coarse_hierarchy.current_level, params)
    // 2. Hierarchical stitching: cluster, patch fractional/infeasible parts into a feasible candidate
    clusters ← CLUSTER(x_relaxed, problem_spec, multipliers)
    x_candidate ← PATCHER(x_relaxed, clusters, PARTIAL_OPT, problem_spec, params)
    x_candidate ← repair_if_needed(x_candidate, CONSTRAINTS)
    c ← COST(x_candidate)
    if c < best_cost and validate(x_candidate, CONSTRAINTS): x_best, best_cost ← x_candidate, c
    // 3. Compute constraint violation subgradient and update multipliers (Polyak/diminishing)
    subgrad ← compute_violations(x_candidate, CONSTRAINTS); step ← step_size_schedule(subgrad, params)
    multipliers ← max(0, multipliers + step * subgrad)
    // 4. Targeted intensive improvement on high-violation or high-impact clusters
    hotspots ← select_hotspots(subgrad, clusters, params.hotspot_threshold)
    for h in hotspots: x_candidate ← PARTIAL_OPT(x_candidate, h, problem_spec, params)
    // 5. Adaptive hierarchy control and stochastic perturbation for diversification
    if stagnation_detected(): coarse_hierarchy := descend_or_recoarsen(coarse_hierarchy); multipliers := random_perturb(multipliers, params)
  return DECODE(x_best)

Algorithm CALD(problem_spec, time_limit, seed)
  // Cooperative Adaptive Learning and Decomposition (task-agnostic)
  Init hooks := ENCODE, DECODE, COST, VALIDATE, REPAIR, OPERATORS, DECOMPOSE, BUILD_MODEL, SURROGATE
  population := SeedPopulation(problem_spec, seed, heuristics+random); archive := {}; specialists := InitSpecialists(problem_spec)
  for s in population: s := REPAIR(s); s.cost := COST(s); if VALIDATE(s) add_to(archive,s)
  model := BUILD_MODEL(population, archive); operator_weights := uniform(OPERATORS); credits := zero(OPERATORS)
  while not STOP(time_limit, iteration, stagnation):
    subproblems := DECOMPOSE(population, model, specialists)            // multi-scale clusters / blocks / routes
    budget_plan := AllocateBudget(subproblems, model, archive, adaptivity)
    for sub in Prioritize(subproblems, budget_plan):
      parent := SelectParent(population, archive, sub, fitness+diversity+specialist_bias)
      op := ContextualChoose(operator_weights, op_context=sub, model)
      child := APPLY_OPERATOR_RESTRICTED(parent, op, sub)               // operator acts only on focused part
      child := REPAIR(child); child := LOCAL_IMPROVE(child, sub, OPERATORS.local)
      child.cost := SURROGATE_EVAL(child, model, fallback=ExactEvalSampled)
      credits[op] += CreditFunction(parent, child, feasibility_gain, novelty)
      population, archive, specialists := CooperativeIngest(population, archive, specialists, child, replace_policy)
    operator_weights := AdaptWeights(operator_weights, credits, decay, exploration_strategy)
    if Periodic(model_update_interval): model := BUILD_MODEL(population, archive); specialists := UpdateSpecialists(model, population)
    if Periodic(recombine_interval): population := RecombineElites(archive, model, OPERATORS.recombine)
  return DecodeBest(archive)

